/*fix for the checkout extension */

(function () {
  const origFetch = window.fetch;
  window.fetch = async function (input, init) {
    const res = await origFetch.apply(this, arguments);
    try {
      const url = typeof input === 'string' ? input : input.url;
      if (/\/cart\/(add|update)\.js/.test(url)) {
        const cart = await origFetch('/cart.js?_si_starter=true').then(r => r.json());
        const line = cart.items.find(i => i.handle === 'shipinsure' && !(i.properties || {})._added_from);
        if (line) {
          await origFetch('/cart/change.js?_si_starter=true', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ id: line.key, quantity: line.quantity, properties: { ...line.properties, _added_from: 'shipinsure' } })
          });
        }
      }
    } catch (e) { console.error('SI _added_from:', e); }
    return res;
  };
})();



/*To fix the disable button */

(function () {
  if (window.__siCheckoutDisabledSync) return;
  window.__siCheckoutDisabledSync = true;

  var CLONE_SELECTOR = '._si-checkout-1852';
  var scheduled = false;

  function syncDisabled() {
    scheduled = false;
    document.querySelectorAll(CLONE_SELECTOR).forEach(function (clone) {
      var original = clone.previousElementSibling;
      if (!original || original.tagName !== 'BUTTON') return;
      if (clone.disabled !== original.disabled) {
        clone.disabled = original.disabled;
      }
    });
  }

  function scheduleSync() {
    if (scheduled) return;
    scheduled = true;
    requestAnimationFrame(syncDisabled);
  }

  syncDisabled();
  new MutationObserver(scheduleSync).observe(document.documentElement, {
    subtree: true,
    childList: true,
    attributes: true,
    attributeFilter: ['disabled']
  });
})(); 

